import {drawTrainerIntro} from './trainer-duel.js?v=32';
export function drawMatchPresentation(c,view){if(view.trainerMode){drawTrainerIntro(c,view);return;}const s=view.matchIntro;if(!s)return;const t=Math.max(0,Math.min(1,((view.presentationTime||0)-s.start)/s.duration)),fade=Math.min(1,t*8,(1-t)*8);c.save();c.globalAlpha=fade;
 c.fillStyle='#080f1ae0';c.fillRect(0,245,540,470);c.strokeStyle='#73818e';c.lineWidth=1;c.strokeRect(25,265,490,430);c.fillStyle='#e9cd89';c.font='bold 11px monospace';c.textAlign='center';c.fillText(s.arena,270,292,460);c.fillStyle='#a9b9c8';c.font='10px monospace';c.fillText(s.format,270,313,450);
 for(let team=0;team<2;team++){const color=team?'#edc56f':'#f18c7b',y=team?565:343,slide=(1-Math.min(1,t*6))*(team?50:-50);c.save();c.translate(slide,0);c.fillStyle=team?'#322c20':'#302129';c.fillRect(44,y,452,116);c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.moveTo(44,y);c.lineTo(496,y);c.stroke();const ids=s.lineups[team],step=ids.length===1?0:72;for(const [i,id] of ids.entries()){const image=view.images['intro-'+id],x=270+(i-(ids.length-1)/2)*step;if(image){c.imageSmoothingEnabled=false;c.drawImage(image,x-28,y+10,56,56)}else{c.fillStyle=color;c.font='bold 24px monospace';c.fillText('◆',x,y+46)}}c.fillStyle=color;c.font='bold 19px monospace';c.fillText(s.names[team],270,y+96,424);c.restore();}
 c.fillStyle='#fff1ce';c.font='bold italic 47px monospace';c.fillText('VS',270,520);c.strokeStyle='#d8bb75';c.lineWidth=1;c.beginPath();c.moveTo(65,504);c.lineTo(208,504);c.moveTo(332,504);c.lineTo(475,504);c.stroke();c.restore();}
